353	  commandFinishEverything(): Observable<CommandResponse> {
354	    // Finish targets come from a fresh complete snapshot. Keep the visible
355	    // filter and auto-selection intact if the operation fails or is cancelled.
356	    const group = this.groupName;
357	    const revision = this.connectionRevision;
358	    const scope = this.bs.accessSignal;
359	    const current = () => !!group && revision === this.connectionRevision &&
360	      group === this.groupName && scope === this.bs.accessSignal && !scope.aborted;
361	    // Rendered rows may still await XML, or retain an older poll. Finish uses
362	    // one fresh complete native snapshot, then keeps those exact targets even
363	    // when the successful lock changes later snapshots to status=locked.
364	    return defer(() => current() ? this.bs.getSessionsMonitor(group).pipe(
365	      take(1),
366	      switchMap(rows => {
367	        if (!current()) return EMPTY;
368	        const unlocked = rows.filter(row => BigInt(row.testId) > 0n &&
369	          !TestSessionUtil.hasState(row.testState, 'status', 'locked'));
370	        const lockIds = unlocked.map(row => row.testId);
371	        const pending = new Set(this.bs.pendingFinishTargets(group));
372	        const eligible = rows.filter(row => BigInt(row.testId) > 0n &&
373	          !TestSessionUtil.hasState(row.testState, 'status', 'pending') &&
374	          !TestSessionUtil.hasState(row.testState, 'CONTROLLER', 'TERMINATED'));
375	        const remaining = new Set(eligible.map(row => row.testId));
376	        for (const id of pending) if (!remaining.has(id)) pending.delete(id);
377	        const terminateIds = eligible.filter(row => pending.has(row.testId) ||
378	          (!TestSessionUtil.hasState(row.testState, 'status', 'locked') &&
379	            (TestSessionUtil.hasState(row.testState, 'CONNECTION', 'POLLING') ||
380	              TestSessionUtil.hasState(row.testState, 'CONNECTION', 'WEBSOCKET'))))
381	          .map(row => row.testId);
382	        // Retain before writing: even an error/abort can follow a committed
383	        // lock. A retry uses a fresh snapshot without adopting unrelated locks.
384	        terminateIds.forEach(id => pending.add(id));
385	        this.bs.rememberFinishTargets(group, [...pending]);
386	        return this.bs.lock(group, lockIds).pipe(
387	          delay(1500),
388	          mergeMap(() => current() ? this.bs.command('terminate', ['lock'], terminateIds) : EMPTY),
389	          tap(() => {
390	            if (current()) this.bs.rememberFinishTargets(group,
391	              this.bs.pendingFinishTargets(group).filter(id => !terminateIds.includes(id)));
392	          })
393	        );
394	      }),
395	      takeUntil(this.disconnected$),
396	      takeUntil(fromEvent(scope, 'abort'))
397	    ) : EMPTY);
398	  }
