400	  sortSessions(sort: Sort, sessions: TestSession[]): TestSession[] {
401	    return sessions
402	      .sort((session1, session2) => {
403	        const sortDirectionFactor = (sort.direction === 'asc' ? 1 : -1);
404	        if (sort.active === 'timestamp') {
405	          return (session1.data.timestamp - session2.data.timestamp) * sortDirectionFactor;
406	        }
407	        if (sort.active === '_checked') {
408	          const session1isChecked = this.isChecked(session1);
409	          const session2isChecked = this.isChecked(session2);
410	          if (!session1isChecked && session2isChecked) {
411	            return 1 * sortDirectionFactor;
412	          }
413	          if (session1isChecked && !session2isChecked) {
414	            return -1 * sortDirectionFactor;
415	          }
416	          return 0;
417	        }
418	        if (sort.active === '_superState') {
419	          return (TestSessionsSuperStates.indexOf(session1.state) -
420	            TestSessionsSuperStates.indexOf(session2.state)) * sortDirectionFactor;
421	        }
422	        if (sort.active === '_currentBlock') {
423	          const s1curBlock = session1.current?.ancestor?.blockId ?? 'zzzzzzzzzz';
424	          const s2curBlock = session2.current?.ancestor?.blockId ?? 'zzzzzzzzzz';
425	          return s1curBlock.localeCompare(s2curBlock) * sortDirectionFactor;
426	        }
427	        if (sort.active === '_currentUnit') {
428	          const s1currentUnit = session1.current?.unit?.label ?? 'zzzzzzzzzz';
429	          const s2currentUnit = session2.current?.unit?.label ?? 'zzzzzzzzzz';
430	          return s1currentUnit.localeCompare(s2currentUnit) * sortDirectionFactor;
431	        }
432	        if (sort.active.startsWith('bookletState:')) {
433	          const bookletState = sort.active.replace('bookletState:', '');
434	          const label = (session: TestSession): string =>
435	            TestSessionUtil.bookletStateLabel(session, bookletState) ?? 'zzzzzzzzzz';
436	          const a = label(session1);
437	          const b = label(session2);
438	          return a.localeCompare(b) * sortDirectionFactor;
439	        }
440	        let valA = session1.data[sort.active as keyof typeof session1.data] ?? 'zzzzzzzzzz';
441	        let valB = session2.data[sort.active as keyof typeof session2.data] ?? 'zzzzzzzzzz';
442	        if (typeof valA === 'number') {
443	          valA = valA.toString(10);
444	        }
445	        if (typeof valB === 'number') {
446	          valB = valB.toString(10);
447	        }
448	        if ((typeof valA === 'object') || (typeof valB === 'object')) {
449	          return 0;
450	        }
451	        return valA.localeCompare(valB) * sortDirectionFactor;
452	      });
453	  }
