      (this.dialogData.cancelbuttonlabel.length === 0)
    ) {
      this.dialogData.cancelbuttonlabel = 'Abbrechen';
    }
  }

  confirm(): void {
    // Read the control at the click, not a mat-dialog-close input cached by
