      'Fällen jedoch sicher fortgesetzt werden, da der Fehler wahrscheinlich auf der Seite des ' +
      'Monitors liegt.'
  }
};import type { Testlet, TestSession } from '../group-monitor.interfaces';

export class TimeLeftPipe {
  // eslint-disable-next-line class-methods-use-this
  transform(testSession: TestSession, testlet: Testlet): number | false {
    return (testSession.timeLeft !== null) &&
    (testSession.timeLeft[testlet.id] !== undefined) &&
    (testSession.timeLeft[testlet.id] >= 0) ?
      testSession.timeLeft[testlet.id] :
      false;
  }
}
import type { Testlet, TestSession } from '../group-monitor.interfaces';

export class IsCodeClearPipe {
  // eslint-disable-next-line class-methods-use-this
  transform(testSession: TestSession, testlet: Testlet) {
    return testSession.clearedCodes && testSession.clearedCodes.includes(testlet.id);
  }
}import { isBooklet, type Testlet, type TestSession } from '../group-monitor.interfaces';

export class TestletvisiblePipe {
  // eslint-disable-next-line class-methods-use-this
  transform(session: TestSession, testlet: Testlet): boolean {
    if (!isBooklet(session.booklet)) return false;
    if (!testlet.restrictions.show) return true;
    const current = (session.bookletStates && session.bookletStates[testlet.restrictions.show.if]) ?
      session.bookletStates[testlet.restrictions.show.if] :
      session.booklet.states[testlet.restrictions.show.if].default;
    return current === testlet.restrictions.show.is;
  }
}
import { isBooklet, type TestSession } from '../group-monitor.interfaces';

export class BookletStatesPipe {
  // eslint-disable-next-line class-methods-use-this
  transform(testSession: TestSession, state: string, stateOption: string): { state: string; option: string } | false {
    if (!isBooklet(testSession.booklet)) return false;
    return {
      state: testSession.booklet.states[state]?.label || state,
      option: testSession.booklet.states[state]?.options[stateOption]?.label || stateOption
    };
  }
